const expected = $('Sample requests').all().map(item => item.json);
const rows = $input.all().map(item => item.json);
const ids = rows.map(row => row.request_id);
const missing = expected.filter(item => !ids.includes(item.request_id)).map(item => item.request_id);
const valid = rows.every(row => {
  const original = expected.find(item => item.request_id === row.request_id);
  return original && row.ok === true && row.normalized_email === original.email.trim().toLowerCase();
});
return [{json:{passed:rows.length === expected.length && new Set(ids).size === expected.length && missing.length === 0 && valid, expected_count:expected.length, returned_count:rows.length, returned_ids:ids, missing_ids:missing, normalized_emails:rows.map(row => row.normalized_email ?? null), child_batch_sizes:rows.map(row => row.child_batch_size ?? null)}}];
